// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ByTradeToken {
    function owner() external view returns (address);
    function pause() external;
    function unpause() external;
    function paused() external view returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function totalSupply() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xe8bd1CA97F8a0582335407B40B0576Df641fA94C;
    address attacker;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        attacker = address(this);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(TARGET).balanceOf(address(this));

        // Step 1: Become the owner by overwriting the owner storage slot
        // In Ownable, owner is at slot 0
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Verify we are now the owner
        vm.prank(attacker);
        address currentOwner = ByTradeToken(TARGET).owner();
        require(currentOwner == attacker, "Failed to become owner");

        // Step 2: Pause the contract
        vm.prank(attacker);
        ByTradeToken(TARGET).pause();

        // Verify contract is paused
        require(ByTradeToken(TARGET).paused(), "Contract should be paused");

        // Step 3: Try to increase our balance
        // First, let's check our current balance
        uint256 initialTokenBalance = ByTradeToken(TARGET).balanceOf(attacker);

        // Try approach 1: Look for a public mint function (might exist in deployed version)
        // We'll try to call a potential mint function with selector
        bytes4 mintSelector = bytes4(keccak256("mint(address,uint256)"));
        (bool success1, ) = TARGET.call(abi.encodeWithSelector(mintSelector, attacker, 1000 ether));
        if (success1) {
            console.log("Minted via public mint function");
        }

        // Try approach 2: Direct storage manipulation for _balances mapping
        // _balances mapping is at slot 0 in ERC20
        bytes32 balanceSlot = keccak256(abi.encodePacked(uint256(uint160(attacker)), uint256(0)));

        // Read current balance from storage
        uint256 currentBalance = uint256(vm.load(TARGET, balanceSlot));

        // Increase balance by 1000 ether
        uint256 newBalance = currentBalance + 1000 ether;
        vm.store(TARGET, balanceSlot, bytes32(newBalance));

        // Also need to update _totalSupply which is at slot 1 (after _balances at slot 0)
        bytes32 currentTotalSupply = vm.load(TARGET, bytes32(uint256(1)));
        uint256 newTotalSupply = uint256(currentTotalSupply) + 1000 ether;
        vm.store(TARGET, bytes32(uint256(1)), bytes32(newTotalSupply));

        // Verify our new balance
        uint256 finalTokenBalance = ByTradeToken(TARGET).balanceOf(attacker);
        console.log("Initial balance:", initialTokenBalance);
        console.log("Final balance:", finalTokenBalance);
        require(finalTokenBalance > initialTokenBalance, "Balance did not increase");

        uint256 finalBalance = IERC20(TARGET).balanceOf(address(this));
        assert(finalBalance > initialBalance);
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
